import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

it('preserves non-Error rejection causes and caller values [specs/hal-engine-config-hooks/spec.md#8]', async () => {
  const values: unknown[] = ['string boom', {code: 503}, undefined];
  const results = [];
  for (const reason of values) {
    const provider: AIProvider = {
      // eslint-disable-next-line require-yield
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        throw reason;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const session: ChatSession = {sessionId: 's', userId: 'u', entries: []};
    const seen: Error[] = [];
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
      hooks: {onError: async (_session, error) => void seen.push(error)},
    });
    const outcome = await orchestrator.processMessage(session).then(
      () => ({rejected: false, original: false}),
      (error: unknown) => ({rejected: true, original: error === reason})
    );
    results.push({outcome, count: seen.length, isError: seen[0] instanceof Error, cause: seen[0]?.cause === reason});
  }
  expect(results).toEqual(values.map(() => ({outcome: {rejected: true, original: true}, count: 1, isError: true, cause: true})));
});
EOF
 timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js --runInBand --runTestsByPath src/orchestration/onErrorCause.test.ts"
